mkdir -p /tmp/w && cat > /tmp/w/gen.js <<'EOF'
const A="123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
function enc(buf){let z=0;while(z<buf.length&&buf[z]===0)z++;let n=0n;for(const x of buf)n=n*256n+BigInt(x);let s="";while(n>0n){s=A[Number(n%58n)]+s;n/=58n;}return A[0].repeat(z)+s;}
function decCorrect(v){let z=0;while(z<v.length&&v[z]===A[0])z++;let n=0n;for(const ch of v.slice(z)){const i=A.indexOf(ch);n=n*58n+BigInt(i);}const out=[];while(n>0n){out.unshift(Number(n%256n));n/=256n;}return Buffer.concat([Buffer.alloc(z),Buffer.from(out)]);}
function decNaiveHex(v){let z=0;while(z<v.length&&v[z]===A[0])z++;let n=0n;for(const ch of v.slice(z)){n=n*58n+BigInt(A.indexOf(ch));}let h=n.toString(16);return Buffer.concat([Buffer.alloc(z),Buffer.from(h,"hex")]);}
function decNaiveLen(v){ // pads/truncates to input length (common wrong assumption)
  let z=0;while(z<v.length&&v[z]===A[0])z++;let n=0n;for(const ch of v.slice(z)){n=n*58n+BigInt(A.indexOf(ch));}
  const out=[];while(n>0n){out.unshift(Number(n%256n));n/=256n;}
  const b=Buffer.from(out); const want=v.length-z; return Buffer.concat([Buffer.alloc(z), b.length<want?Buffer.concat([Buffer.alloc(want-b.length),b]):b]);}
function pyrepr(s){const hasS=s.includes(0x27),hasD=s.includes(0x22);const q=(hasS&&!hasD)?'"':"'";let o="b"+q;for(const b of s){if(b===0x5c)o+="\\\\";else if(b===q.charCodeAt(0))o+="\\"+q;else if(b===0x09)o+="\\t";else if(b===0x0a)o+="\\n";else if(b===0x0d)o+="\\r";else if(b<0x20||b>=0x7f)o+="\\x"+b.toString(16).padStart(2,"0");else o+=String.fromCharCode(b);}return o+q;}
module.exports={A,enc,decCorrect,decNaiveHex,decNaiveLen,pyrepr};
EOF
cat > /tmp/w/mkvecs.js <<'EOF'
const {enc}=require('/tmp/w/gen.js');
function rnd(n){const b=Buffer.alloc(n);for(let i=0;i<n;i++)b[i]=Math.floor(Math.random()*256);return b;}
const vecs=[];
// biased: values whose hex is odd-length (top nibble 0), trailing zeros, leading zeros
for(let i=0;i<400;i++){
  const len=1+Math.floor(Math.random()*12);
  let b=rnd(len);
  const m=i%5;
  if(m===0)b[0]=Math.floor(Math.random()*16);           // top nibble 0 -> odd hex
  if(m===1){b[0]=1; for(let k=1;k<len;k++)b[k]=0;}       // 1 then trailing zeros
  if(m===2){const z=Math.floor(Math.random()*Math.min(4,len));for(let k=0;k<z;k++)b[k]=0;}
  if(m===3){const t=Math.floor(Math.random()*Math.min(4,len));for(let k=len-t;k<len;k++)b[k]=0; b[0]=b[0]||1;}
  if(m===4){b=Buffer.alloc(len);}                        // all zeros
  vecs.push(b.toString('hex'));
}
for(const v of vecs)console.log(v+" "+(enc(Buffer.from(v,'hex'))||''));
EOF
