const fs=require('fs');
const {enc,decCorrect,decNaiveHex,decNaiveLen,pyrepr}=require('/tmp/w/gen.js');
const lines=fs.readFileSync('/tmp/w/actual.txt','utf8').trim().split('\n');
let okC=0,badC=[],badHex=[],badLen=[],ecBad=[];
for(const L of lines){
  const [h,e,ec,act]=L.split('\t');
  if(ec!=='0')ecBad.push(L);
  const c=pyrepr(decCorrect(e));
  const nh=pyrepr(decNaiveHex(e));
  const nl=pyrepr(decNaiveLen(e));
  if(c===act)okC++;else badC.push([h,e,act,c]);
  if(nh!==act)badHex.push([h,e,act,nh]);
  if(nl!==act)badLen.push([h,e,act,nl]);
  // also confirm hex round-trips: correct decode must equal original hex bytes
  if(decCorrect(e).toString('hex')!==h) badC.push([h,e,'ROUNDTRIP-MISMATCH',decCorrect(e).toString('hex')]);
}
console.log('total',lines.length,'exit!=0:',ecBad.length);
console.log('CORRECT(pad-even / repeated divmod) mismatches:',badC.length);
badC.slice(0,10).forEach(r=>console.log('  C-MISS',r.join(' | ')));
console.log('NAIVE toString(16) mismatches:',badHex.length);
badHex.slice(0,12).forEach(r=>console.log('  HEXBUG hex='+r[0]+' b58='+r[1]+' binary='+r[2]+' naive='+r[3]));
console.log('NAIVE pad-to-input-length mismatches:',badLen.length);
badLen.slice(0,12).forEach(r=>console.log('  LENBUG hex='+r[0]+' b58='+r[1]+' binary='+r[2]+' naive='+r[3]));
EOF
